// Every word on a Now screen comes from the CPO's string table (strings.js, generated by tools/studio-strings.mjs).
// t('catalog.count', { n: 2 }) → "2 on the team". A missing key shows the key itself, so it is easy to spot.
import { EN } from './strings.js';

// Words the Studio needs that the strings file does not have yet. Each one is asked of the CPO; when the strings
// file has it, it comes from there (EN wins) and the line here is deleted.
const PENDING = {
  'nav.meetings': 'Meetings',
  // L27: the account page's Security heading (B3 named the tab Security), asked of the CPO.
  'security.title': 'Security',
};

export function t(key, vars = {}) {
  // A count of one has its own string when the file gives one ("canvas.changes.one").
  if (vars.n === 1 && EN[`${key}.one`] !== undefined) key = `${key}.one`;
  const s = EN[key] ?? PENDING[key];
  if (s === undefined) return key;
  return s.replace(/\{([^}]+)\}/g, (m, k) => (vars[k] ?? m));
}

/** The tooltip for a glossary word or control, or '' when the table has none. */
export const tip = (key) => EN[`tip.${key}`] ?? '';
